-- Cart reminder emails: the reminder bookmark on each cart, the opt-out list, and the Marketing / Cart Reminder template.
ALTER TABLE `#__j2commerce_carts` ADD COLUMN `reminder_sent_on` datetime DEFAULT NULL /** CAN FAIL **/;
ALTER TABLE `#__j2commerce_carts` ADD INDEX `idx_cart_type_modified` (`cart_type`, `modified_on`) /** CAN FAIL **/;
ALTER TABLE `#__j2commerce_orders` ADD INDEX `idx_cart_id` (`cart_id`) /** CAN FAIL **/;
CREATE TABLE IF NOT EXISTS `#__j2commerce_email_optouts` (
  `j2commerce_email_optout_id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `email_type` varchar(100) NOT NULL,
  `created_on` datetime NOT NULL,
  PRIMARY KEY (`j2commerce_email_optout_id`),
  UNIQUE KEY `idx_email_type` (`email`, `email_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `#__j2commerce_emailtemplates` (`email_type`, `context`, `receiver_type`, `orderstatus_id`, `group_id`, `paymentmethod`, `subject`, `body`, `body_json`, `body_source`, `body_source_file`, `custom_css`, `language`, `enabled`, `ordering`, `core_key`) SELECT 'marketing', 'cart_reminder', 'customer', '*', '*', '*', '[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_SUBJECT]', '<!-- J2Commerce Cart Reminder Email — Modern Template -->\n<div style="display: none; max-height: 0; overflow: hidden; mso-hide: all; font-size: 1px; line-height: 1px; color: [EMAIL_BG_COLOR];">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_PREHEADER]</div>\n<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background-color: [EMAIL_BG_COLOR]; padding: 0; margin: 0; font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 20px 10px;">\n      <table width="600" cellpadding="0" cellspacing="0" border="0" role="presentation" style="max-width: 600px; width: 100%; background-color: #ffffff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td align="center" style="padding: 24px 40px; background-color: #ffffff; border-radius: 12px 12px 0 0; text-align: center;">\n            [IF:STORE_LOGO_URL]\n            <a href="[SITEURL]" target="_blank">\n              <img src="[STORE_LOGO_URL]" alt="[SITENAME]" height="[LOGO_MAX_HEIGHT]" width="[LOGO_WIDTH]" style="display: block; margin: 0 auto; border: 0; height: [LOGO_MAX_HEIGHT]px; width: auto;" />\n            </a>\n            [/IF:STORE_LOGO_URL]\n            [IFNOT:STORE_LOGO_URL]\n            <a href="[SITEURL]" target="_blank" style="font-family: Arial, Helvetica, sans-serif; font-size: 22px; font-weight: bold; color: #0F172A; text-decoration: none;">[SITENAME]</a>\n            [/IFNOT:STORE_LOGO_URL]\n          </td>\n        </tr>\n\n        <!-- Reminder Banner -->\n        <tr>\n          <td style="background-color: #F8FAFC; padding: 32px 40px; text-align: center; border-top: 1px solid #E2E8F0; border-bottom: 1px solid #E2E8F0;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation">\n              <tr>\n                <td align="center">\n                  <table cellpadding="0" cellspacing="0" border="0" role="presentation" style="margin-bottom: 16px;">\n                    <tr>\n                      <td align="center" style="width: 64px; height: 64px; background-color: [ACCENT_COLOR]; border-radius: 50%; text-align: center; vertical-align: middle;">\n                        <span aria-hidden="true" style="font-size: 30px; line-height: 64px;">&#x1F6D2;</span>\n                      </td>\n                    </tr>\n                  </table>\n                  <h1 style="font-family: Arial, Helvetica, sans-serif; font-size: 26px; font-weight: 800; color: #0F172A; margin: 0 0 12px;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_HEADING]</h1>\n                  [IF:FIRST_NAME]<p style="font-family: Arial, Helvetica, sans-serif; font-size: 16px; color: #334155; line-height: 1.5; margin: 0 0 4px;">[LANG:COM_J2COMMERCE_EMAIL_HI]</p>[/IF:FIRST_NAME]\n                  <p style="font-family: Arial, Helvetica, sans-serif; font-size: 16px; color: #334155; line-height: 1.5; margin: 0;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_INTRO]</p>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Primary CTA -->\n        <tr>\n          <td align="center" style="background-color: #ffffff; padding: 28px 40px 8px;">\n            <table cellpadding="0" cellspacing="0" border="0" role="presentation">\n              <tr>\n                <td align="center" style="background-color: [ACCENT_COLOR]; border-radius: 8px;">\n                  <a href="[CART_URL]" target="_blank" style="font-family: Arial, Helvetica, sans-serif; font-size: 16px; font-weight: bold; color: [ACCENT_TEXT_COLOR]; text-decoration: none; display: inline-block; padding: 14px 40px; min-height: 20px;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_BUTTON]</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Cart Items Card -->\n        <tr>\n          <td style="box-sizing: border-box; background-color: #ffffff; padding: 24px 40px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #E2E8F0; border-radius: 10px; overflow: hidden;">\n              <!-- Card Header -->\n              <tr>\n                <td colspan="3" style="background-color: #F8FAFC; padding: 14px 20px; border-bottom: 1px solid #E2E8F0;">\n                  <h2 style="font-family: Arial, Helvetica, sans-serif; font-size: 15px; font-weight: 700; color: #0F172A; margin: 0;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_ITEMS]</h2>\n                </td>\n              </tr>\n              <!-- Column Headers -->\n              <tr>\n                <th scope="col" colspan="2" style="padding: 10px 20px; font-family: Arial, Helvetica, sans-serif; font-size: 11px; font-weight: bold; color: #475569; text-transform: uppercase; letter-spacing: 0.5px; text-align: left;">[LANG:COM_J2COMMERCE_EMAIL_PRODUCT]</th>\n                <th scope="col" style="padding: 10px 20px; font-family: Arial, Helvetica, sans-serif; font-size: 11px; font-weight: bold; color: #475569; text-transform: uppercase; letter-spacing: 0.5px; text-align: center; width: 45px;">[LANG:COM_J2COMMERCE_EMAIL_QTY]</th>\n              </tr>\n              <!-- Items -->\n              <!--[ITEMS_LOOP]-->\n              <tr>\n                <td style="padding: 12px 0 12px 20px; border-top: 1px solid #F1F5F9; vertical-align: top; width: 60px;">\n                  [IF:ITEM_IMAGE]\n                  <img src="[ITEM_IMAGE]" alt="[ITEM_NAME]" width="50" height="50" style="border-radius: 6px; object-fit: cover; display: block; border: 1px solid #F1F5F9;" />\n                  [/IF:ITEM_IMAGE]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #F1F5F9; vertical-align: top; font-family: Arial, Helvetica, sans-serif;">\n                  <span style="font-size: 14px; font-weight: 600; color: #0F172A;">[ITEM_NAME]</span>\n                  [IF:ITEM_SKU]<br /><span style="font-size: 12px; color: #475569;">[LANG:COM_J2COMMERCE_EMAIL_SKU_2]</span>[/IF:ITEM_SKU]\n                  [IF:ITEM_OPTIONS]<br /><span style="font-size: 12px; color: #475569;">[ITEM_OPTIONS]</span>[/IF:ITEM_OPTIONS]\n                </td>\n                <td style="padding: 12px 20px; border-top: 1px solid #F1F5F9; text-align: center; vertical-align: top; font-family: Arial, Helvetica, sans-serif; font-size: 14px; color: #0F172A;">[ITEM_QTY]</td>\n              </tr>\n              <!--[/ITEMS_LOOP]-->\n            </table>\n          </td>\n        </tr>\n\n        <!-- Applied Coupon -->\n        <!--[IF:CART_COUPON]-->\n        <tr>\n          <td style="background-color: #ffffff; padding: 0 40px 24px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background-color: #F8FAFC; border: 1px dashed #64748B; border-radius: 10px;">\n              <tr>\n                <td style="padding: 16px 20px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 14px; color: #334155;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_COUPON]</td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <!--[/IF:CART_COUPON]-->\n\n        <!-- Support Block -->\n        <!--[IF:STORE_EMAIL]-->\n        <tr>\n          <td style="background-color: #ffffff; padding: 0 40px 24px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background-color: #F8FAFC; border-radius: 10px;">\n              <tr>\n                <td style="padding: 20px; text-align: center; font-family: Arial, Helvetica, sans-serif;">\n                  <h2 style="font-family: Arial, Helvetica, sans-serif; font-size: 14px; font-weight: 600; color: #0F172A; margin: 0 0 4px;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_HELP_HEADING]</h2>\n                  <p style="font-size: 13px; color: #475569; margin: 0;">\n                    [LANG:COM_J2COMMERCE_EMAIL_CONTACT_US_AT] <a href="mailto:[STORE_EMAIL]" style="color: #334155; text-decoration: underline;">[STORE_EMAIL]</a>\n                  </p>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <!--[/IF:STORE_EMAIL]-->\n\n        <!-- Footer -->\n        <tr>\n          <td style="padding: 24px 40px; background-color: #ffffff; border-radius: 0 0 12px 12px; border-top: 1px solid #F1F5F9; text-align: center; font-family: Arial, Helvetica, sans-serif;">\n            <p style="font-size: 12px; color: #475569; margin: 0 0 12px; line-height: 1.6;">\n              [IF:SOCIAL_FACEBOOK]<a href="[SOCIAL_FACEBOOK]" style="color: #475569; text-decoration: underline; margin: 0 6px;">Facebook</a>[/IF:SOCIAL_FACEBOOK]\n              [IF:SOCIAL_INSTAGRAM]<a href="[SOCIAL_INSTAGRAM]" style="color: #475569; text-decoration: underline; margin: 0 6px;">Instagram</a>[/IF:SOCIAL_INSTAGRAM]\n              [IF:SOCIAL_TWITTER]<a href="[SOCIAL_TWITTER]" style="color: #475569; text-decoration: underline; margin: 0 6px;">X (Twitter)</a>[/IF:SOCIAL_TWITTER]\n            </p>\n            <p style="font-size: 12px; color: #475569; margin: 0; line-height: 1.6;">[FOOTER_TEXT]</p>\n            <p style="font-size: 12px; color: #475569; margin: 8px 0 0; line-height: 1.6;">\n              [STORE_NAME][IF:STORE_ADDRESS_1] &middot; [STORE_ADDRESS_1][/IF:STORE_ADDRESS_1][IF:STORE_ADDRESS_2], [STORE_ADDRESS_2][/IF:STORE_ADDRESS_2][IF:STORE_CITY], [STORE_CITY][/IF:STORE_CITY][IF:STORE_STATE], [STORE_STATE][/IF:STORE_STATE] [STORE_ZIP][IF:STORE_COUNTRY], [STORE_COUNTRY][/IF:STORE_COUNTRY]\n            </p>\n            <p style="font-size: 12px; color: #475569; margin: 8px 0 0; line-height: 1.6;">\n              [LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_WHY] <a href="[UNSUBSCRIBE_URL]" style="color: #475569; text-decoration: underline;">[LANG:COM_J2COMMERCE_EMAIL_CART_REMINDER_UNSUBSCRIBE]</a>\n            </p>\n            <p style="font-size: 12px; color: #475569; margin: 8px 0 0;">\n              &copy; [CURRENT_YEAR] <a href="[SITEURL]" style="color: #475569; text-decoration: underline;">[SITENAME]</a>. [LANG:COM_J2COMMERCE_EMAIL_ALL_RIGHTS_RESERVED]\n            </p>\n          </td>\n        </tr>\n\n      </table>\n    </td>\n  </tr>\n</table>\n', '', 'visual', '', '', '*', 1, 5, 'email.cartreminder.customer' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `#__j2commerce_emailtemplates` WHERE `core_key` = 'email.cartreminder.customer');
